// unplaced depth today; the contract above holds regardless, so a future
// caller that does needs no change here.
func isNearerOwner(depth, bestDepth int, state, best *SessionState) bool {
	if (depth >= 0) != (bestDepth >= 0) {
		return depth >= 0
	}
	if depth >= 0 {
